import React, { useEffect } from 'react';
import './App.css';
// import Header from '../Header/Header'; // ...existing code... (закомментировано)
// import Login from '../../pages/Login'; // ...existing code... (закоментовано)
import Calendar from '../Calendar/Calendar'; // добавлено
import '../Calendar/';

export default function App() {
    useEffect(() => {
        const prevMargin = document.body.style.margin;
        const prevOverflowY = document.body.style.overflowY;
        document.body.style.margin = '0';
        document.body.style.overflowY = 'hidden';
        return () => {
            document.body.style.margin = prevMargin;
            document.body.style.overflowY = prevOverflowY;
        };
    }, []);

    return (
        <div className="app" style={{ height: '100vh', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
            {/* <Header /> */} {/* закомментировано */}
            <div style={{ flex: 1, overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {/* <Login /> */} {/* закомментовано */}
                <Calendar /> {/* подключён Calendar */}
            </div>
        </div>
    );
}
